schema:
CREATE TABLE users (user_id TEXT NOT NULL PRIMARY KEY, username TEXT DEFAULT NULL);
CREATE TABLE channels (channel_id TEXT NOT NULL PRIMARY KEY, channel_type TEXT DEFAULT NULL);
CREATE TABLE direct_links (user_a TEXT NOT NULL, user_b TEXT NOT NULL, channel_id TEXT DEFAULT NULL, PRIMARY KEY (user_a, user_b), FOREIGN KEY (user_a) REFERENCES users (user_id), FOREIGN KEY (user_b) REFERENCES users (user_id), FOREIGN KEY (channel_id) REFERENCES channels (channel_id));
